"use client";
// Client entry points for the inventory actions (generated by scripts/gen-actions.py).
// Each call POSTs to /api/actions/inventory/<name>; implementations live in src/server/actions-impl/inventory.ts.
import { remoteAction } from "@/lib/remote-action";

export const createProductAction = remoteAction("inventory", "createProductAction");
export const receiveStockAction = remoteAction("inventory", "receiveStockAction");
export const sellStockAction = remoteAction("inventory", "sellStockAction");
export const returnStockAction = remoteAction("inventory", "returnStockAction");
export const adjustStockAction = remoteAction("inventory", "adjustStockAction");
export const transferStockAction = remoteAction("inventory", "transferStockAction");
export const createWarehouseAction = remoteAction("inventory", "createWarehouseAction");
